    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2021 Higher Level — © State Examinations Commission.",
    id: "eng-2021-hl-q6-b-i", topicId: "eng-2-10", conceptId: "aid-diagram-s-suitable-welding-process",
    section: "A", questionRef: "2021 HL Q6(b)(i)",
    questionText: "Describe, with the aid of a diagram(s), a suitable welding process to manufacture the girders for the bridge shown.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "In submerged arc welding, a bare wire electrode is used. It is fed automatically from a spool and generates an electric arc to heat the metal. The flux, in powder form, is fed from a hopper to completely cover the joint and the tip of the electrode. The arc creates the heat to melt the joint, flux and electrode.", marks: null },
    { id: "r-2", kind: "point", verbatim: "A slag is formed to provide a protective coating for the weld. The excess flux powder can be collected and used again. Submerged arc welding is a fully automated process.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Applications: used for large-scale straight-line welds such as steel reinforcing beams, shipbuilding and bridge construction.", marks: null },
    ],
