    section: "A", questionRef: "2025 HL Q3(a)(i)",
    stem: "compressor blade",
    questionText: "Explain the term metal fatigue.",
    tariffModel: {"kind":"fixed"}, totalMarks: 4,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Metal fatigue is the initiation and propagation of cracks in a material due to cyclic loading (on/off loading). Once a fatigue crack has initiated, it grows a small amount with each loading cycle. The crack will continue to grow until it reaches a critical size and complete fracture of the structure.", marks: 4 },
    ],
