    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2025 Higher Level — © State Examinations Commission.",
    id: "eng-2025-hl-q6-b-i", topicId: "eng-2-10", conceptId: "identify-necessary-steps-preparation-joint-welding",
    section: "A", questionRef: "2025 HL Q6(b)(i)",
    questionText: "Identify two necessary steps in the preparation of a joint for welding.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Clean the surfaces to be welded by removing dirt, grease, oil and rust. Use a wire brush, grinder or chemical cleaner.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Ensure there are no sharp edges or burrs on the metal pieces by grinding or filing them down.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Ensure the metal pieces are correctly aligned and close fitting, for thicker materials, bevel the edges using a grinder or cutting tool.", marks: null },
    { id: "r-4", kind: "point", verbatim: "Ensure that the angles and alignment are accurate and secure the workpieces using clamps, jigs, or fixtures.", marks: null },
    { id: "r-5", kind: "point", verbatim: "Some metals, like high-carbon steel or thick materials, may require preheating to prevent cracking. Use a torch or heating element to bring the metal to the desired temperature.", marks: null },
    ],
